"""Generate platform-specific CMake build scripts."""

from __future__ import annotations

import argparse
from pathlib import Path
from typing import Callable


Format = str
Section = Callable[[Format], list[str]]
ROOT = Path(__file__).resolve().parent


def header(target: Format) -> list[str]:
    if target == "cmd":
        return [
            "@echo off",
            "@rem Generated by generate_build.py. Do not edit this file directly.",
            "setlocal EnableExtensions",
            'set "PROJECT_ROOT=%~dp0.."',
            'set "SOURCE_DIR=%PROJECT_ROOT%\\src"',
        ]
    return [
        "#!/usr/bin/env bash",
        "# Generated by generate_build.py. Do not edit this file directly.",
        "set -euo pipefail",
        'script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"',
        'source_dir="$(cd -- "$script_dir/.." && pwd)/src"',
    ]


def arguments(target: Format) -> list[str]:
    if target == "cmd":
        return [
            'set "BACKEND=%~1"',
            'set "CONFIG=%~2"',
            'set "TOOLCHAIN=%~3"',
            'if "%BACKEND%"=="" goto :usage',
            'if "%CONFIG%"=="" set "CONFIG=Debug"',
            'if "%TOOLCHAIN%"=="" set "TOOLCHAIN=auto"',
            'if defined PYTHON_EXECUTABLE set "PYTHON_OPTIONS=-DPython_EXECUTABLE=%PYTHON_EXECUTABLE% -DPython3_EXECUTABLE=%PYTHON_EXECUTABLE%"',
            'if /I "%BACKEND%"=="opengl" set "BACKEND_OPTIONS=-DUSE_OPENGL40=ON"',
            'if /I "%BACKEND%"=="directx" set "BACKEND_OPTIONS=-DUSE_OPENGL40=OFF"',
            'if /I "%BACKEND%"=="vulkan" goto :vulkan',
            'if "%BACKEND_OPTIONS%"=="" goto :usage',
            'if /I "%TOOLCHAIN%"=="auto" goto :auto',
            'if /I "%TOOLCHAIN%"=="visualstudio" goto :visualstudio',
            'if /I "%TOOLCHAIN%"=="clang" goto :clang',
            'if /I "%TOOLCHAIN%"=="gcc" goto :gcc',
            "goto :usage",
        ]
    return [
        'backend="${1:-}"',
        'config="${2:-Debug}"',
        'toolchain="${3:-auto}"',
        'case "$backend" in',
        'opengl) backend_options=(-DUSE_OPENGL40=ON) ;;',
        'directx) backend_options=(-DUSE_OPENGL40=OFF) ;;',
        '*) echo "Unsupported backend: $backend" >&2; exit 1 ;;',
        "esac",
    ]


def cmd_toolchains(_: Format) -> list[str]:
    return [
        ":auto",
        'set "AUTO_FALLBACK=ON"',
        "goto :visualstudio",
        ":visualstudio",
        'set "VSWHERE=%ProgramFiles(x86)%\\Microsoft Visual Studio\\Installer\\vswhere.exe"',
        'if not exist "%VSWHERE%" goto :visualstudio_unavailable',
        '"%VSWHERE%" -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -version "[18.0,19.0)" -property installationPath | findstr.exe /r /c:"." >nul',
        "if not errorlevel 1 set \"GENERATOR=Visual Studio 18 2026\"",
        'if not defined GENERATOR "%VSWHERE%" -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -version "[17.0,18.0)" -property installationPath | findstr.exe /r /c:"." >nul',
        "if not defined GENERATOR if not errorlevel 1 set \"GENERATOR=Visual Studio 17 2022\"",
        "if not defined GENERATOR goto :visualstudio_unavailable",
        'set "BUILD_DIR=%~dp0%BACKEND%\\visualstudio"',
        'set "DEFAULT_TRIPLET=x64-windows"',
        "goto :build_visualstudio",
        ":visualstudio_unavailable",
        'if /I "%AUTO_FALLBACK%"=="ON" goto :clang',
        "echo Visual Studio 18 2026 or Visual Studio 17 2022 was not found.",
        "exit /b 1",
        ":clang",
        "where.exe ninja >nul 2>nul || goto :clang_unavailable",
        "where.exe clang >nul 2>nul || goto :clang_unavailable",
        'set "BUILD_DIR=%~dp0%BACKEND%\\clang"',
        'set "DEFAULT_TRIPLET=x64-windows"',
        'set "COMPILER_OPTIONS=-DCMAKE_C_COMPILER=clang -DCMAKE_CXX_COMPILER=clang++"',
        "goto :build_ninja",
        ":clang_unavailable",
        'if /I "%AUTO_FALLBACK%"=="ON" goto :gcc',
        "echo Clang or Ninja was not found.",
        "exit /b 1",
        ":gcc",
        "where.exe ninja >nul 2>nul || goto :gcc_unavailable",
        "where.exe gcc >nul 2>nul || goto :gcc_unavailable",
        "where.exe g++ >nul 2>nul || goto :gcc_unavailable",
        'set "BUILD_DIR=%~dp0%BACKEND%\\gcc"',
        'set "DEFAULT_TRIPLET=x64-mingw-dynamic"',
        'set "COMPILER_OPTIONS=-DCMAKE_C_COMPILER=gcc -DCMAKE_CXX_COMPILER=g++"',
        "goto :build_ninja",
        ":gcc_unavailable",
        "echo GCC or Ninja was not found.",
        "exit /b 1",
    ]


def cmd_packages(_: Format) -> list[str]:
    return [
        ":configure_packages",
        'set "PACKAGE_OPTIONS="',
        "if defined CMAKE_TOOLCHAIN_FILE set \"PACKAGE_OPTIONS=\"-DCMAKE_TOOLCHAIN_FILE=%CMAKE_TOOLCHAIN_FILE%\"\"",
        "if defined VCPKG_INSTALLED_DIR set \"PACKAGE_OPTIONS=%PACKAGE_OPTIONS% -DVCPKG_INSTALLED_DIR=%VCPKG_INSTALLED_DIR%\"",
        "if defined CMAKE_TOOLCHAIN_FILE exit /b 0",
        'if not defined VCPKG_ROOT if defined VCPKG_INSTALLATION_ROOT set "VCPKG_ROOT=%VCPKG_INSTALLATION_ROOT%"',
        "if not defined VCPKG_ROOT for /f \"delims=\" %%I in ('where.exe vcpkg.exe 2^>nul') do if not defined VCPKG_ROOT for %%J in (\"%%I\") do set \"VCPKG_ROOT=%%~dpJ\"",
        "if not defined VCPKG_ROOT goto :vcpkg_missing",
        'set "VCPKG_TOOLCHAIN=%VCPKG_ROOT%\\scripts\\buildsystems\\vcpkg.cmake"',
        'if not exist "%VCPKG_TOOLCHAIN%" goto :vcpkg_missing',
        'if not defined VCPKG_TARGET_TRIPLET set "VCPKG_TARGET_TRIPLET=%DEFAULT_TRIPLET%"',
        'set "PACKAGE_OPTIONS="-DCMAKE_TOOLCHAIN_FILE=%VCPKG_TOOLCHAIN%" -DVCPKG_TARGET_TRIPLET=%VCPKG_TARGET_TRIPLET%"',
        "if defined VCPKG_INSTALLED_DIR set \"PACKAGE_OPTIONS=%PACKAGE_OPTIONS% -DVCPKG_INSTALLED_DIR=%VCPKG_INSTALLED_DIR%\"",
        "exit /b 0",
        ":vcpkg_missing",
        "echo vcpkg was not found. Set VCPKG_ROOT or CMAKE_TOOLCHAIN_FILE.",
        "exit /b 1",
    ]


def cmd_builds(_: Format) -> list[str]:
    return [
        ":build_visualstudio",
        "call :configure_packages",
        "if errorlevel 1 exit /b %errorlevel%",
        'cmake -S "%SOURCE_DIR%" -B "%BUILD_DIR%" -G "%GENERATOR%" %BACKEND_OPTIONS% %PACKAGE_OPTIONS% %PYTHON_OPTIONS%',
        "if errorlevel 1 exit /b %errorlevel%",
        'cmake --build "%BUILD_DIR%" --config "%CONFIG%"',
        "exit /b %errorlevel%",
        ":build_ninja",
        "call :configure_packages",
        "if errorlevel 1 exit /b %errorlevel%",
        'cmake -S "%SOURCE_DIR%" -B "%BUILD_DIR%" -G Ninja %BACKEND_OPTIONS% %PACKAGE_OPTIONS% %COMPILER_OPTIONS% %PYTHON_OPTIONS% -DCMAKE_BUILD_TYPE=%CONFIG%',
        "if errorlevel 1 exit /b %errorlevel%",
        'cmake --build "%BUILD_DIR%"',
        "exit /b %errorlevel%",
        ":vulkan",
        "echo Vulkan build support has not been added to CMake yet.",
        "exit /b 1",
        ":usage",
        "echo Usage: %~nx0 ^<opengl^|directx^> [config] [auto^|visualstudio^|clang^|gcc]",
        "exit /b 1",
    ]


def sh_functions(_: Format) -> list[str]:
    return [
        "usage() { echo \"Usage: $(basename \"$0\") <opengl|directx> [config] [auto|clang|gcc]\" >&2; exit 1; }",
        "configure_packages() {",
        "    package_options=()",
        '    [[ -n "${CMAKE_TOOLCHAIN_FILE:-}" ]] && { package_options=("-DCMAKE_TOOLCHAIN_FILE=$CMAKE_TOOLCHAIN_FILE"); return; }',
        '    [[ -z "${VCPKG_ROOT:-}" ]] && command -v vcpkg >/dev/null && VCPKG_ROOT="$(dirname "$(command -v vcpkg)")"',
        '    [[ -f "${VCPKG_ROOT:-}/scripts/buildsystems/vcpkg.cmake" ]] || { echo "Set VCPKG_ROOT or CMAKE_TOOLCHAIN_FILE." >&2; exit 1; }',
        '    package_options=("-DCMAKE_TOOLCHAIN_FILE=$VCPKG_ROOT/scripts/buildsystems/vcpkg.cmake" "-DVCPKG_TARGET_TRIPLET=${VCPKG_TARGET_TRIPLET:-x64-linux}")',
        "}",
    ]


def sh_build(_: Format) -> list[str]:
    return [
        'if [[ "$toolchain" == auto ]]; then',
        '    command -v clang >/dev/null && command -v ninja >/dev/null && toolchain=clang || toolchain=gcc',
        "fi",
        'case "$toolchain" in',
        'clang) compiler_options=(-DCMAKE_C_COMPILER=clang -DCMAKE_CXX_COMPILER=clang++); ;;',
        'gcc) compiler_options=(-DCMAKE_C_COMPILER=gcc -DCMAKE_CXX_COMPILER=g++); ;;',
        '*) usage ;;',
        "esac",
        'command -v "$toolchain" >/dev/null && command -v ninja >/dev/null || { echo "Compiler or Ninja was not found." >&2; exit 1; }',
        "configure_packages",
        'build_dir="$script_dir/$backend/$toolchain"',
        'cmake -S "$source_dir" -B "$build_dir" -G Ninja "${backend_options[@]}" "${package_options[@]}" "${compiler_options[@]}" -DCMAKE_BUILD_TYPE="$config"',
        'cmake --build "$build_dir"',
    ]


def render(target: Format) -> str:
    sections: tuple[Section, ...]
    if target == "cmd":
        sections = (header, arguments, cmd_toolchains, cmd_packages, cmd_builds)
    else:
        sections = (header, sh_functions, arguments, sh_build)

    lines: list[str] = []
    for section in sections:
        if lines:
            lines.append("")
        lines.extend(section(target))
    return "\n".join(lines) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--format", choices=("cmd", "sh"), default="cmd")
    parser.add_argument("--output", type=Path)
    arguments = parser.parse_args()
    output = arguments.output or ROOT / ("build.cmd" if arguments.format == "cmd" else "build.sh")
    output.write_text(render(arguments.format), encoding="utf-8")


if __name__ == "__main__":
    main()
